$json$::jsonb) as x(ci int, b text, a text, s jsonb)
  loop
    select chunk_text into t from public.rag_corpus
     where author = 'Xenophon' and work = 'Memorabilia' and program_id = 'stoicism-phd'
       and deprecated = false and chunk_index = rec.ci;
    if t is null then raise exception 'Memorabilia chunk % not found', rec.ci; end if;
    if md5(t) = rec.a then continue; end if;  -- already cleaned
    if md5(t) <> rec.b then raise exception 'Memorabilia chunk % is not the text the spans were computed on', rec.ci; end if;

    insert into public.rag_corpus (
      program_id, author, work, section_label, chunk_index, chunk_text, word_count,
      translator, source_url, text_type, embedding, course_relevance, difficulty,
      source_chunk_index, language, paired_chunk_id, source_type, parent_chunks,
      deprecated, edition_year, locator
    )
    select
      r.program_id, r.author, r.work, r.section_label,
      (select max(r2.chunk_index) + 1 from public.rag_corpus r2
        where r2.author = r.author and r2.work = r.work and r2.program_id = r.program_id),
      r.chunk_text, r.word_count,
      r.translator, r.source_url, r.text_type, r.embedding, r.course_relevance, r.difficulty,
      r.source_chunk_index, r.language, r.paired_chunk_id, r.source_type, r.parent_chunks,
      true, r.edition_year, r.locator
    from public.rag_corpus r
    where r.author = 'Xenophon' and r.work = 'Memorabilia' and r.program_id = 'stoicism-phd'
      and r.deprecated = false and r.chunk_index = rec.ci;

    for sp in
      select (e.value->>0)::int as off, (e.value->>1)::int as len
        from jsonb_array_elements(rec.s) with ordinality as e(value, n)
       order by e.n desc
    loop
      t := overlay(t placing '' from sp.off + 1 for sp.len);
    end loop;
    t := btrim(regexp_replace(t, '\s{2,}', ' ', 'g'));
    if md5(t) <> rec.a then raise exception 'Memorabilia chunk % did not clean to the expected text', rec.ci; end if;
    update public.rag_corpus
       set chunk_text = t,
           word_count = case when word_count is null then null
                             else array_length(regexp_split_to_array(t, '\s+'), 1) end
     where author = 'Xenophon' and work = 'Memorabilia' and program_id = 'stoicism-phd'
       and deprecated = false and chunk_index = rec.ci;
  end loop;
end
$$;
